const items = $input.all();
const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});
const dateShort = new Date().toISOString().split('T')[0];

const headlines = items
  .map(item => (item.json.title || '').replace(/<[^>]*>/g, '').trim())
  .filter(t => t.length > 3)
  .slice(0, 8)
  .map((t, i) => `${i + 1}. ${t}`)
  .join('\n');

const systemPrompt = `You are a tweet writer for an AI-focused X (Twitter) account. Your voice mirrors Naval Ravikant and James Clear: spare, wise, aphoristic, punchline-obsessed. Every tweet creates a pause — the reader encounters a truth they could not articulate before you said it.

Generate exactly 12 tweets about AI. Distribute across these categories (at least 1-2 per):
- "Fine Detail" — a specific, under-appreciated technical or behavioral insight about AI
- "High-Level" — a sweeping perspective on AI's arc or place in history
- "Optimistic" — genuine, non-clichéd hope about what AI unlocks
- "Pessimistic" — honest concern, a dark truth most people avoid saying
- "Philosophical" — a deep question about consciousness, identity, or meaning as it relates to AI
- "Contrarian" — challenges a dominant AI narrative (hype or doom alike)
- "Trending" — directly inspired by today's news headlines; use 2-3 of these

Rules (non-negotiable):
1. Every tweet MUST be 280 characters or fewer. Count every character before returning.
2. No hashtags, no emojis, no links, no @ mentions.
3. The final line must be a hard punchline — the whole tweet builds to it.
4. Do not start more than 2 tweets with "The".
5. Vary structure: questions, paradoxes, declarations — mix them.
6. Earn every insight. No surface-level takes. No filler.

Return ONLY this exact JSON. No markdown wrapper, no explanation, no preamble:
{"tweets":[{"content":"tweet text","category":"Fine Detail","news_inspired":"headline title or null"}]}`;

const userMessage = `Date: ${today}\n\nToday's trending AI headlines:\n${headlines}\n\nGenerate 12 tweets now. Max 280 chars each. Return only JSON.`;

const requestBody = {
  model: 'gpt-4o',
  response_format: { type: 'json_object' },
  temperature: 0.85,
  max_tokens: 3000,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userMessage }
  ]
};

return [{ json: { dateShort, headlines, requestBody } }];

const items = $input.all();
const item = items[0];

const content = item.json?.choices?.[0]?.message?.content || '';
if (!content) {
  throw new Error('No content in OpenAI response');
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  const match = content.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); }
    catch (e2) { throw new Error('Failed to parse tweets JSON: ' + content.substring(0, 200)); }
  } else {
    throw new Error('No JSON in OpenAI response: ' + content.substring(0, 200));
  }
}

const tweets = parsed.tweets || [];
const today = new Date().toISOString().split('T')[0];

if (tweets.length === 0) {
  throw new Error('No tweets returned in parsed response');
}

return tweets.map((tweet, index) => {
  const text = (tweet.content || '').trim();
  const finalText = text.length > 280 ? text.substring(0, 277) + '...' : text;
  return {
    json: {
      date: today,
      category: tweet.category || 'Uncategorized',
      tweet: finalText,
      char_count: finalText.length,
      news_inspired: tweet.news_inspired || 'Original',
      status: '',
      tweet_number: index + 1
    }
  };
});
